/**
 * India's states and union territories, as ready-to-draw SVG paths.
 *
 * Generated once from Natural Earth's 1:50m admin-1 dataset (public domain, no
 * attribution required) and checked in, so the map needs no runtime fetch, no
 * map provider and no API key. Coordinates are Web Mercator, scaled to the
 * viewBox below and rounded to a tenth of a unit; rings closer together than
 * that, and islands smaller than a few units across, are dropped.
 *
 * To regenerate: take ne_50m_admin_1_states_provinces.geojson, keep the
 * features whose `admin` is "India", and run them through the same Mercator +
 * scale as {@link projectIndia}.
 */

/** The box every path below is drawn in. */
export const INDIA_VIEWBOX = { w: 1000, h: 1071 };

/** Mercator bounds the paths were built against; {@link projectIndia} undoes them. */
const LNG_MIN = 68.165039;
const MERC_MAX = 38.0120393475457;
const SCALE = 34.27180032645945;

const mercatorY = (lat: number) =>
  Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360)) * (180 / Math.PI);

/**
 * Puts a coordinate exactly where the paths put it, so a pin can never drift
 * off the state it belongs to.
 */
export function projectIndia(lng: number, lat: number) {
  return {
    x: (lng - LNG_MIN) * SCALE,
    y: (MERC_MAX - mercatorY(lat)) * SCALE,
  };
}

